import React, { useState } from 'react';
import { Nav, Button } from 'react-bootstrap';
import { Link, useLocation } from 'react-router-dom';
import {
    LayoutDashboard,
    UserPlus,
    User,
    ChevronLeft,
    ChevronRight,
    Building2
} from 'lucide-react';

const Sidebar = ({ role }) => {
    const [collapsed, setCollapsed] = useState(false);
    const location = useLocation();

    const adminLinks = [
        { to: '/', label: 'Dashboard', icon: <LayoutDashboard size={18} /> },
        { to: '/add-employee/_add', label: 'Add Employee', icon: <UserPlus size={18} /> },
    ];

    const employeeLinks = [
        { to: '/dashboard', label: 'My Profile', icon: <User size={18} /> },
    ];

    const links = role === 'ADMIN' ? adminLinks : employeeLinks;

    const sidebarStyle = {
        width: collapsed ? '70px' : '230px',
        minHeight: '100vh',
        background: '#f4f5f7',
        borderRight: '1px solid #dde1e7',
        transition: 'width 0.25s ease',
        display: 'flex',
        flexDirection: 'column',
        position: 'relative',
        overflow: 'hidden',
    };

    const brandStyle = {
        display: 'flex',
        alignItems: 'center',
        gap: '10px',
        padding: collapsed ? '20px 0' : '20px 18px',
        justifyContent: collapsed ? 'center' : 'flex-start',
        borderBottom: '1px solid #dde1e7',
        background: '#fff',
    };

    const linkStyle = (isActive) => ({
        display: 'flex',
        alignItems: 'center',
        gap: '12px',
        padding: collapsed ? '12px 0' : '11px 18px',
        justifyContent: collapsed ? 'center' : 'flex-start',
        borderRadius: '8px',
        margin: '3px 8px',
        color: isActive ? '#1a1a2e' : '#5a6273',
        background: isActive ? '#e2e5ea' : 'transparent',
        fontWeight: isActive ? '600' : '400',
        fontSize: '14px',
        textDecoration: 'none',
        transition: 'all 0.15s ease',
        whiteSpace: 'nowrap',
        overflow: 'hidden',
    });

    const roleTagStyle = {
        fontSize: '10px',
        fontWeight: '700',
        letterSpacing: '0.08em',
        color: '#8a93a2',
        textTransform: 'uppercase',
        padding: collapsed ? '16px 0 6px' : '16px 26px 6px',
        textAlign: collapsed ? 'center' : 'left',
    };

    const toggleBtnStyle = {
        position: 'absolute',
        bottom: '24px',
        right: collapsed ? '50%' : '12px',
        transform: collapsed ? 'translateX(50%)' : 'none',
        background: '#fff',
        border: '1px solid #dde1e7',
        borderRadius: '8px',
        padding: '6px 10px',
        color: '#5a6273',
        cursor: 'pointer',
        transition: 'all 0.25s ease',
        display: 'flex',
        alignItems: 'center',
    };

    return (
        <div style={sidebarStyle}>
            {/* Brand */}
            <div style={brandStyle}>
                <Building2 size={22} color="#374151" strokeWidth={2} />
                {!collapsed && (
                    <span style={{ fontWeight: '700', fontSize: '16px', color: '#1a1a2e', letterSpacing: '0.04em' }}>
                        EMS
                    </span>
                )}
            </div>

            {/* Nav Links */}
            <Nav className="flex-column mt-2" style={{ flex: 1 }}>
                <div style={roleTagStyle}>
                    {collapsed ? '•' : role === 'ADMIN' ? 'Admin' : 'Employee'}
                </div>

                {links.map((link) => {
                    const isActive = location.pathname === link.to;
                    return (
                        <Link
                            key={link.to}
                            to={link.to}
                            style={linkStyle(isActive)}
                            onMouseEnter={e => {
                                if (!isActive) e.currentTarget.style.background = '#eaecf0';
                            }}
                            onMouseLeave={e => {
                                if (!isActive) e.currentTarget.style.background = 'transparent';
                            }}
                        >
                            <span style={{ flexShrink: 0 }}>{link.icon}</span>
                            {!collapsed && <span>{link.label}</span>}
                        </Link>
                    );
                })}
            </Nav>

            {/* Collapse Toggle */}
            <button
                style={toggleBtnStyle}
                onClick={() => setCollapsed(!collapsed)}
                title={collapsed ? 'Expand' : 'Collapse'}
            >
                {collapsed ? <ChevronRight size={16} /> : <ChevronLeft size={16} />}
            </button>
        </div>
    );
};

export default Sidebar;
